import re
for tag in ('0','1024'):
    txt=open(f'/tmp/dm-pad{tag}.txt',errors='replace').read()
    prints=[]
    for ln in txt.splitlines():
        t=float(re.match(r'\[\s*([0-9.]+)\]',ln).group(1)) if re.match(r'\[\s*([0-9.]+)\]',ln) else None
        m=re.search(r'create_bo: size=0x([0-9a-f]+) flags=0x([0-9a-f]+) handle=(\d+) iova=0x([0-9a-f]+)',ln)
        if m: prints.append(('bo',t,int(m.group(1),16),int(m.group(3)),int(m.group(4),16)))
        m=re.search(r'MMU fault AS0: (\S+) stat ([0-9a-f]+) addr ([0-9a-f]+)',ln)
        if m: prints.append(('fault',t,m.group(1),int(m.group(2),16),int(m.group(3),16)))
    bos=[p for p in prints if p[0]=='bo']; fs=[p for p in prints if p[0]=='fault']
    print(f'--- pad={tag} ---')
    for f in fs:
        addr=f[4]; where=[]
        for b in bos:
            if b[4] <= addr < b[4]+b[2]:
                where.append(f'IN h{b[3]} off=0x{addr-b[4]:x}')
        top=max(b[4]+b[2] for b in bos)
        print(f'fault t={f[1]:.3f} {f[2]} stat=0x{f[3]:x} addr=0x{addr:x} -> {where or "NOT in any BO"} top=0x{top:x} (top-addr=0x{top-addr:x})')
    print('BOs:', ', '.join(f'h{b[3]}:0x{b[4]:x}+0x{b[2]:x}' for b in bos))
EOF

